pm.test('Status is 200', () => pm.response.to.have.status(200));
const body = pm.response.json();
pm.test('Message Token refreshed.', () => pm.expect(body.message).to.eql('Token refreshed.'));
pm.test('New access + refresh token', () => {
  pm.expect(body.data.accessToken).to.be.a('string').and.not.empty;
  pm.expect(body.data.refreshToken).to.be.a('string').and.not.eql(pm.collectionVariables.get('refreshToken'));
});
pm.collectionVariables.set('oldRefreshToken', pm.collectionVariables.get('refreshToken'));
pm.collectionVariables.set('accessToken', body.data.accessToken);
pm.collectionVariables.set('refreshToken', body.data.refreshToken);

